Lex["0342"] = "'eybah {ay-baw'}|AV - enmity 3, hatred 2; 5|from 0340|TWOT - 78a|noun feminine| INDENT0--<b>1)</b> enmity, hatred <br /><BR /><hr /> INDENT0--<b>Strong\'s Definition</b><BR><BR> INDENT0--<span style=\"font-size:150%\"> &#1488;&#1461;&#1497;&#1489;&#1464;&#1492;</span> &#700;&#234;yb&#226;h, ay-baw&#39;; from Strong\'s <a href=\"strongs_hebrew.html?strongs=340&page=1\">H340</a>; hostility:&#8212;emnity, hatred.";
Lex["0343"] = "'eyd {ade}|AV - calamity 17, destruction 7; 24|from the same as 0181 (in the sense of bending down)|TWOT - 38c|noun masculine| INDENT0--<b>1)</b> distress, burden, calamity INDENT3--<b>a)</b> burden (of the righteous) INDENT3--<b>b)</b> calamity (of nation)<BR> INDENT3--<b>c)</b> disaster (of wicked) INDENT3--<b>d)</b> day of calamity <br /><BR /><hr /> INDENT0--<b>Strong\'s Definition</b><BR><BR> INDENT0--<span style=\"font-size:150%\"> &#1488;&#1461;&#1497;&#1491;</span> &#700;&#234;yd, ade; from the same as Strong\'s <a href=\"strongs_hebrew.html?strongs=181&page=1\">H181</a> (in the sense of bending down); oppression; by implication misfortune, ruin:&#8212;calamity, destruction.";
