Lex["0448"] = "'Eliy'athah {el-ee-aw-thaw'} or (contraction)<BR>'Eliyathah {el-ee-yaw-thaw'}|AV - Eliathah 2; 2|from 0410 and 0225||noun proper masculine|<br><br>Eliathah = \"God has come\"<BR> INDENT0--<b>1)</b> a Hemanite musician in David's court <br /><BR /><hr /> INDENT0--<b>Strong\'s Definition</b><BR><BR> INDENT0--<span style=\"font-size:150%\"> &#1488;&#1457;&#1500;&#1460;&#1497;&#1488;&#1464;&#1514;&#1464;&#1492;</span> &#700;&#276;l&#238;y&#700;&#226;th&#226;h, el-ee-aw-thaw&#39;; or (contraction) <span style=\"font-size:150%\"> &#1488;&#1457;&#1500;&#1460;&#1497;&#1468;&#1464;&#1514;&#1464;&#1492;</span> &#x2BC;&#x114;l&#xEE;y&#xE2;th&#xE2;h; from Strong\'s <a href=\"strongs_hebrew.html?strongs=410&page=1\">H410</a> and Strong\'s <a href=\"strongs_hebrew.html?strongs=225&page=1\">H225</a>; God of (his) consent; Eliathah, an Israelite:&#8212;Eliathah.";
Lex["0449"] = "'Eliydad {el-ee-dawd'}|AV - Elidad 1; 1|from the same as 0419||noun proper masculine|<br><br>Elidad = \"my God has loved\"<BR> INDENT0--<b>1)</b> a Benjamite chief who helped apportion his tribe's allotment to the Promised Land <br /><BR /><hr /> INDENT0--<b>Strong\'s Definition</b><BR><BR> INDENT0--<span style=\"font-size:150%\"> &#1488;&#1457;&#1500;&#1460;&#1497;&#1491;&#1464;&#1491;</span> &#700;&#276;l&#238;yd&#226;d, el-ee-dawd&#39;; from the same as Strong\'s <a href=\"strongs_hebrew.html?strongs=419&page=1\">H419</a>; God of (his) love; Elidad, an Israelite:&#8212;Elidad.";
Lex["0450"] = "'Elyada` {el-yaw-daw'}|AV - Eliada 3, Eliadah 1; 4|from 0410 and 03045||noun proper masculine|<br><Br>Eliadah or Eliada = \"God knows\"<BR> INDENT0--<b>1)</b> a son of David INDENT0--<b>2)</b> a Benjamite warrior chief INDENT0--<b>3)</b> an Aramean, the father of an enemy of Solomon <br /><BR /><hr /> INDENT0--<b>Strong\'s Definition</b><BR><BR> INDENT0--<span style=\"font-size:150%\"> &#1488;&#1462;&#1500;&#1456;&#1497;&#1464;&#1491;&#1464;&#1506;</span> &#700;Ely&#226;d&#226;&#699;, el-yaw-daw&#39;; from Strong\'s <a href=\"strongs_hebrew.html?strongs=410&page=1\">H410</a> and Strong\'s <a href=\"strongs_hebrew.html?strongs=3045&page=1\">H3045</a>; God (is) knowing; Eljada, the name of two Israelites and of an Aramaean leader:&#8212;Eliada.";
Lex["0451"] = "'alyah {al-yaw'}|AV - rump 5; 5|from 0422 (in the original sense of strength)|TWOT - 95a|noun feminine| INDENT0--<b>1)</b> tail, fat-tail (of sheep - an Eastern delicacy) <br /><BR /><hr /> INDENT0--<b>Strong\'s Definition</b><BR><BR> INDENT0--<span style=\"font-size:150%\"> &#1488;&#1463;&#1500;&#1456;&#1497;&#1464;&#1492;</span> &#700;aly&#226;h, al-yaw&#39;; from Strong\'s <a href=\"strongs_hebrew.html?strongs=422&page=1\">H422</a> (in the original sense of strength); the stout part, i.e. the fat tail of the Oriental sheep:&#8212;rump.";
Lex["0452"] = "'Eliyah {ay-lee-yaw'} or prolonged 'Eliyahuw {ay-lee-yaw'-hoo}|AV - Elijah 69, Eliah 2; 71|from 0410 and 03050||noun proper masculine|<br><br>Elijah or Eliah = \"my God is Jehovah\" or \"Yah(u) is God\"<BR> INDENT0--<b>1)</b> the great prophet of the reign of Ahab INDENT0--<b>2)</b> Benjamite son of Jeroham INDENT0--<b>3)</b> a son of Elam with foreign wife during exile INDENT0--<b>4)</b> a son of Harim, and priest, with foreign wife during exile <br /><BR /><hr /> INDENT0--<b>Strong\'s Definition</b><BR><BR> INDENT0--<span style=\"font-size:150%\"> &#1488;&#1461;&#1500;&#1460;&#1497;&#1468;&#1464;&#1492;</span> &#700;&#234;l&#238;y&#226;h, ay-lee-yaw&#39;; or prolonged <span style=\"font-size:150%\"> &#1488;&#1461;&#1500;&#1460;&#1497;&#1468;&#1464;&#1492;&#1493;&#1468; </span> &#x2BC;&#xCA;l&#xEE;y&#xE2;h&#xFB;w; from Strong\'s <a href=\"strongs_hebrew.html?strongs=410&page=1\">H410</a> and Strong\'s <a href=\"strongs_hebrew.html?strongs=3050&page=1\">H3050</a>; God of Jehovah; Elijah, the name of the famous prophet and of two other Israelites:&#8212;Elijah, Eliah.";
