Lex["0639"] = "'aph {af}|AV - anger 172, wrath 42, face 22, nostrils 13, nose 12, angry 4,<BR>longsuffering + 0750 4, before 2, countenance 1, forbearing 1,<BR>forehead 1, snout 1, worthy 1; 276|from 0599|TWOT - 133a|noun masculine| INDENT0--<b>1)</b> nostril, nose, face INDENT0--<b>2)</b> anger <br /><BR /><hr /> INDENT0--<b>Strong\'s Definition</b><BR><BR> INDENT0--<span style=\"font-size:150%\"> &#1488;&#1463;&#1507;</span> &#700;aph, af; from Strong\'s <a href=\"strongs_hebrew.html?strongs=599&page=1\">H599</a>; properly, the nose or nostril; hence, the face, and occasionally a person; also (from the rapid breathing in passion) ire:&#8212;anger(-gry), before, countenance, face, forebearing, forehead, (long-) suffering, nose, nostril, snout, <sup><b><a href=\"#strongs-legend\">X</a></b></sup> worthy, wrath.";
