Lex["0856"] = "'Ethba`al {eth-bah'-al}|AV - Ethbaal 1; 1|from 0854 and 01168||noun proper masculine|<br><br>Ethbaal = \"with Baal\"<BR> INDENT0--<b>1)</b> king of Sidon, father of Jezebel <br /><BR /><hr /> INDENT0--<b>Strong\'s Definition</b><BR><BR> INDENT0--<span style=\"font-size:150%\"> &#1488;&#1462;&#1514;&#1456;&#1489;&#1468;&#1463;&#1506;&#1463;&#1500;</span> &#700;Ethba&#699;al, eth-bah&#39;-al; from Strong\'s <a href=\"strongs_hebrew.html?strongs=854&page=1\">H854</a> and Strong\'s <a href=\"strongs_hebrew.html?strongs=1168&page=1\">H1168</a>; with Baal; Ethbaal, a Phoenician king:&#8212;Ethbaal.";
Lex["0857"] = "'athah {aw-thaw'} or 'atha' {aw-thaw'}|AV - come 20, brought 1; 21|a primitive root [collateral to 0225 contraction]|TWOT - 188|verb| INDENT0--<b>1)</b> to come, arrive INDENT3--<b>a)</b> (Qal) to come (of men, time, beasts, calamity) INDENT3--<b>b)</b> (Hiphil) to bring <br /><BR /><hr /> INDENT0--<b>Strong\'s Definition</b><BR><BR> INDENT0--<span style=\"font-size:150%\"> &#1488;&#1464;&#1514;&#1464;&#1492;</span> &#700;&#226;th&#226;h, aw-thaw&#39;; or <span style=\"font-size:150%\"> &#1488;&#1464;&#1514;&#1464;&#1488; </span>&#x2BC;&#xE2;th&#xE2;&#x2BC;; a primitive root (collateral to Strong\'s <a href=\"strongs_hebrew.html?strongs=225&page=1\">H225</a> contraction); to arrive:&#8212;(be-, things to) come (upon), bring.";
