Lex["03297"] = "Y@`ariym {yeh-aw-reem'}|AV - Jearim 1; 1|pl. of 03293||noun proper locative|<br><br>Jearim = \"forests\"<BR> INDENT0--<b>1)</b> a hill on the northern boundary of Judah <br /><BR /><hr /> INDENT0--<b>Strong\'s Definition</b><BR><BR> INDENT0--<span style=\"font-size:150%\"> &#1497;&#1456;&#1506;&#1464;&#1512;&#1460;&#1497;&#1501;</span>  Y&#7497;&#699;&#226;r&#238;ym, yeh-aw-reem'; plural of Strong\'s <a href=\"strongs_hebrew.html?strongs=3293&page=1\">H3293</a>; forests; Jearim, a place in Palestine:&#8212;Jearim. Compare Strong\'s <a href=\"strongs_hebrew.html?strongs=7157&page=1\">H7157</a>.";
Lex["03298"] = "Ya`areshyah {yah-ar-esh-yaw'}|AV - Jaresiah 1; 1|from an unused root of uncertain signification and 03050||noun proper masculine|<br><br>Jaresiah = \"whom Jehovah nourishes\"<BR> INDENT0--<b>1)</b> a Benjamite, one of the descendants of Jehoram <br /><BR /><hr /> INDENT0--<b>Strong\'s Definition</b><BR><BR> INDENT0--<span style=\"font-size:150%\"> &#1497;&#1463;&#1506;&#1458;&#1512;&#1462;&#1513;&#1473;&#1456;&#1497;&#1464;&#1492;</span>  Ya&#699;&#259;reshy&#226;h, yah-ar-esh-yaw&#39;; from an unused root of uncertain signification and Strong\'s <a href=\"strongs_hebrew.html?strongs=3050&page=1\">H3050</a>; Jaareshjah, an Israelite:&#8212;Jaresiah.";
Lex["03299"] = "Ya`asuw {yah-as-oo'}|AV - Jaasau 1; 1|from 06213||noun proper masculine|<br><br>Jaasau = \"they will do\"<BR> INDENT0--<b>1)</b> one of the descendants of Bani who took a foreign wife during the time of Ezra <br /><BR /><hr /> INDENT0--<b>Strong\'s Definition</b><BR><BR> INDENT0--<span style=\"font-size:150%\"> &#1497;&#1463;&#1506;&#1458;&#1513;&#1474;&#1493;&#1468; </span> Ya&#699;&#259;s&#251;w, yah-as-oo&#39;; from Strong\'s <a href=\"strongs_hebrew.html?strongs=6213&page=1\">H6213</a>; they will do; Jaasu, an Israelite:&#8212;Jaasau.";
