Lex["03301"] = "Yiphd@yah {yif-deh-yaw'}|AV - Iphedeiah 1; 1|from 06299 and 03050||noun proper masculine|<br><br>Iphedeiah = \"Jehovah will redeem\"<BR> INDENT0--<b>1)</b> a descendant of Benjamin and of the family of Shashak <br /><BR /><hr /> INDENT0--<b>Strong\'s Definition</b><BR><BR> INDENT0--<span style=\"font-size:150%\"> &#1497;&#1460;&#1508;&#1456;&#1491;&#1468;&#1456;&#1497;&#1464;&#1492;</span>  Yiphd&#7497;y&#226;h, yif-deh-yaw&#39;; from Strong\'s <a href=\"strongs_hebrew.html?strongs=6299&page=1\">H6299</a> and Strong\'s <a href=\"strongs_hebrew.html?strongs=3050&page=1\">H3050</a>; Jah will liberate; Jiphdejah, an Israelite:&#8212;Iphedeiah.";
Lex["03302"] = "yaphah {yaw-faw'}|AV - fair 4, beautiful 2, deck it 1, fairer 1; 8|A primitive root|TWOT - 890|verb| INDENT0--<b>1)</b> to be bright, be beautiful, be handsome, be fair INDENT3--<b>a)</b> (Qal) to be beautiful INDENT3--<b>b)</b> (Piel) to beautify INDENT3--<b>c)</b> (Pual) to be beautiful INDENT3--<b>d)</b> (Hithpael) to beautify oneself <br /><BR /><hr /> INDENT0--<b>Strong\'s Definition</b><BR><BR> INDENT0--<span style=\"font-size:150%\"> &#1497;&#1464;&#1508;&#1464;&#1492; </span> y&#226;ph&#226;h, yaw-faw&#39;; a primitive root; properly, to be bright, i.e. (by implication) beautiful:&#8212;be beautiful, be (make self) fair(-r), deck.";
Lex["03303"] = "yapheh {yaw-feh'}|AV - fair 21, beautiful 5, well 5, fairest 3, fair one 2, beauty 1,<BR>beautiful + 08389 2, beauty 1, comely 1, pleasant 1; 41|from 03302|TWOT - 890a|adjective| INDENT0--<b>1)</b> fair, beautiful, handsome <br /><BR /><hr /> INDENT0--<b>Strong\'s Definition</b><BR><BR> INDENT0--<span style=\"font-size:150%\"> &#1497;&#1464;&#1508;&#1462;&#1492;</span>  y&#226;pheh, yaw-feh&#39;; from Strong\'s <a href=\"strongs_hebrew.html?strongs=3302&page=1\">H3302</a>; beautiful (literally or figuratively):&#8212; beautiful, beauty, comely, fair(-est, one), goodly, pleasant, well.";
