Lex["03546"] = "k@hal (Aramaic) {keh-hal'}|AV - able 2, could 2; 4|a root corresponding to 03201 and 03557|TWOT - 2785|verb| INDENT0--<b>1)</b> to be able INDENT3--<b>a)</b> (P'al) to be able <br /><BR /><hr /> INDENT0--<b>Strong\'s Definition</b><BR><BR> INDENT0--<span style=\"font-size:150%\"> &#1499;&#1468;&#1456;&#1492;&#1463;&#1500;</span>  k&#7497;hal, keh-hal&#39;; (Aramaic) a root corresponding to and Strong\'s <a href=\"strongs_hebrew.html?strongs=3557&page=1\">H3557</a>; to be able:&#8212;be able, could.";
Lex["03547"] = "kahan {kaw-han'}|AV - priest's office 20, decketh 1, office of a priest 1, priest 1; 23|a primitive root, apparently meaning to mediate in religious services|TWOT - 959|verb| INDENT0--<b>1)</b> to act as a priest, minister in a priest's office INDENT3--<b>a)</b> (Piel) INDENT7--<b>1)</b> to minister as a priest, serve as a priest INDENT7--<b>2)</b> to be or become a priest INDENT7--<b>3)</b> to play the priest <br /><BR /><hr /> INDENT0--<b>Strong\'s Definition</b><BR><BR> INDENT0--<span style=\"font-size:150%\"> &#1499;&#1468;&#1464;&#1492;&#1463;&#1503;</span> k&#226;han, kaw-han&#39;; a primitive root, apparently meaning to mediate in religious services; but used only as denominative from Strong\'s <a href=\"strongs_hebrew.html?strongs=3548&page=1\">H3548</a>; to officiate as a priest; figuratively, to put on regalia:&#8212;deck, be (do the office of a, execute the, minister in the) priest(&#39;s office).";
Lex["03548"] = "kohen {ko-hane'}|AV - priest 744, own 2, chief ruler 2, officer 1, princes 1; 750|active participle of 03547|TWOT - 959a|noun masculine| INDENT0--<b>1)</b> priest, principal officer or chief ruler INDENT3--<b>a)</b> priest-king (Melchizedek, Messiah) INDENT3--<b>b)</b> pagan priests INDENT3--<b>c)</b> priests of Jehovah INDENT3--<b>d)</b> Levitical priests INDENT3--<b>e)</b> Zadokite priests INDENT3--<b>f)</b> Aaronic priests INDENT3--<b>g)</b> the high priest <br /><BR /><hr /> INDENT0--<b>Strong\'s Definition</b><BR><BR> INDENT0--<span style=\"font-size:150%\"> &#1499;&#1468;&#1465;&#1492;&#1461;&#1503;</span> k&#244;h&#234;n, ko-hane&#39;; active participle of Strong\'s <a href=\"strongs_hebrew.html?strongs=3547&page=1\">H3547</a>; literally one officiating, a priest; also (by courtesy) an acting priest (although a layman):&#8212;chief ruler, <sup><b><a href=\"#strongs-legend\">X</a></b></sup> own, priest, prince, principal officer.";
Lex["03549"] = "kahen (Aramaic) {kaw-hane'}|AV - priest 8; 8|corresponding to 03548|TWOT - 2786|noun masculine| INDENT0--<b>1)</b> priest <br /><BR /><hr /> INDENT0--<b>Strong\'s Definition</b><BR><BR> INDENT0--<span style=\"font-size:150%\"> &#1499;&#1468;&#1464;&#1492;&#1461;&#1503;</span> k&#226;h&#234;n, kaw-hane&#39;; (Aramaic) corresponding to Strong\'s <a href=\"strongs_hebrew.html?strongs=3548&page=1\">H3548</a>:&#8212;priest.";
