Lex["03709"] = "kaph {kaf}|AV - hand 128, spoon 24, sole 19, palm 5, hollow 3, handful 2,<BR>apiece 1, branches 1, breadth + 04096 1, clouds 1, misc 7; 192|from 03721|TWOT - 1022a|noun feminine| INDENT0--<b>1)</b> palm, hand, sole, palm of the hand, hollow or flat of the hand INDENT3--<b>a)</b> palm, hollow or flat of the hand INDENT3--<b>b)</b> power INDENT3--<b>c)</b> sole (of the foot) INDENT3--<b>d)</b> hollow, objects, bending objects, bent objects INDENT7--<b>1)</b> of thigh-joint INDENT7--<b>2)</b> pan, vessel (as hollow) INDENT7--<b>3)</b> hollow (of sling) INDENT7--<b>4)</b> hand-shaped branches or fronds (of palm trees) INDENT7--<b>5)</b> handles (as bent) <br /><BR /><hr /> INDENT0--<b>Strong\'s Definition</b><BR><BR> INDENT0--<span style=\"font-size:150%\"> &#1499;&#1468;&#1463;&#1507;</span>  kaph, kaf; from Strong\'s <a href=\"strongs_hebrew.html?strongs=3721&page=1\">H3721</a>; the hollow hand or palm (so of the paw of an animal, of the sole, and even of the bowl of a dish or sling, the handle of a bolt, the leaves of a palm-tree); figuratively, power:&#8212;branch, foot, hand((-ful), -dle, (-led)), hollow, middle, palm, paw, power, sole, spoon.";
Lex["03710"] = "keph {kafe}|AV - rock 2; 2|from 03721|TWOT - 1017|noun masculine| INDENT0--<b>1)</b> rock, hollow of a rock <br /><BR /><hr /> INDENT0--<b>Strong\'s Definition</b><BR><BR> INDENT0--<span style=\"font-size:150%\"> &#1499;&#1468;&#1461;&#1507;</span>  k&#234;ph, kafe; from Strong\'s <a href=\"strongs_hebrew.html?strongs=3721&page=1\">H3721</a>; a hollow rock:&#8212;rock.";
Lex["03711"] = "kaphah {kaw-faw'}|AV - pacify 1; 1|A primitive root|TWOT - 1018|verb| INDENT0--<b>1)</b> (Qal) to sooth, subdue, pacify <br /><BR /><hr /> INDENT0--<b>Strong\'s Definition</b><BR><BR> INDENT0--<span style=\"font-size:150%\"> &#1499;&#1468;&#1464;&#1508;&#1464;&#1492;</span>  k&#226;ph&#226;h, kaw-faw&#39;; a primitive root; properly, to bend, i.e. (figuratively) to tame or subdue:&#8212;pacify.";
Lex["03712"] = "kippah {kip-paw'}|AV - branch 3; 3|from 03709|TWOT - 1022b|noun feminine| INDENT0--<b>1)</b> branch, leaf, frond, palm frond, palm branch <br /><BR /><hr /> INDENT0--<b>Strong\'s Definition</b><BR><BR> INDENT0--<span style=\"font-size:150%\"> &#1499;&#1468;&#1460;&#1508;&#1468;&#1464;&#1492;</span>  kipp&#226;h, kip-paw&#39;; feminine of Strong\'s <a href=\"strongs_hebrew.html?strongs=3709&page=1\">H3709</a>; a leaf of a palmtree:&#8212;branch.";
Lex["03713"] = "k@phowr {kef-ore'}|AV - bason 6, hoar frost 3; 9|from 03722|TWOT - 1026a,1026b|noun masculine| INDENT0--<b>1)</b> bowl, basin INDENT0--<b>2)</b> hoar frost, frost <br /><BR /><hr /> INDENT0--<b>Strong\'s Definition</b><BR><BR> INDENT0--<span style=\"font-size:150%\"> &#1499;&#1468;&#1456;&#1508;&#1493;&#1465;&#1512;</span>  k&#7497;ph&#244;wr, kef-ore&#39;; from Strong\'s <a href=\"strongs_hebrew.html?strongs=3722&page=1\">H3722</a>; properly, a cover, i.e. (by implication) a tankard (or covered goblet); also white frost (as covering the ground):&#8212;bason, hoar(-y) frost.";
Lex["03714"] = "kaphiyc {kaw-fece'}|AV - beam 1; 1|from an unused root meaning to connect|TWOT - 1021a|noun masculine| INDENT0--<b>1)</b> rafter, girder (meaning dubious) <br /><BR /><hr /> INDENT0--<b>Strong\'s Definition</b><BR><BR> INDENT0--<span style=\"font-size:150%\"> &#1499;&#1468;&#1464;&#1508;&#1460;&#1497;&#1505;</span>  k&#226;ph&#238;y&#231;, kaw-fece&#39;; from an unused root meaning to connect; a girder:&#8212;beam.";
Lex["03715"] = "k@phiyr {kef-eer'}|AV - lion 30, villages 1, young 1; 32|from 03722|TWOT - 1025a,1025d|noun masculine| INDENT0--<b>1)</b> young lion INDENT0--<b>2)</b> village <br /><BR /><hr /> INDENT0--<b>Strong\'s Definition</b><BR><BR> INDENT0--<span style=\"font-size:150%\"> &#1499;&#1468;&#1456;&#1508;&#1460;&#1497;&#1512;</span>  k&#7497;ph&#238;yr, kef-eer'; from Strong\'s <a href=\"strongs_hebrew.html?strongs=3722&page=1\">H3722</a>; a village (as covered in by walls); also a young lion (perhaps as covered with a mane):&#8212;(young) lion, village. Compare Strong\'s <a href=\"strongs_hebrew.html?strongs=3723&page=1\">H3723</a>.";
Lex["03716"] = "K@phiyrah {kef-ee-raw'}|AV - Chephirah 4; 4|feminine of 03715||noun proper locative|<br><br>Chephirah = \"lioness\"<BR> INDENT0--<b>1)</b> a city of the Gibeonites subsequently assigned to the tribe of Benjamin <br /><BR /><hr /> INDENT0--<b>Strong\'s Definition</b><BR><BR> INDENT0--<span style=\"font-size:150%\"> &#1499;&#1468;&#1456;&#1508;&#1460;&#1497;&#1512;&#1464;&#1492;</span>  K&#7497;ph&#238;yr&#226;h, kef-ee-raw&#39;; feminine of Strong\'s <a href=\"strongs_hebrew.html?strongs=3715&page=1\">H3715</a>; the village (always with the art.); Kephirah, a place in Palestine:&#8212;Chephirah.";
