Lex["03877"] = "Lowtan {lo-tawn'}|AV - Lotan 7; 7|from 03875||noun proper masculine|<Br><br>Lotan = \"covering\"<BR> INDENT0--<b>1)</b> the eldest son of Seir the Horite <br /><BR /><hr /> INDENT0--<b>Strong\'s Definition</b><BR><BR> INDENT0--<span style=\"font-size:150%\">&#1500;&#1493;&#1465;&#1496;&#1464;&#1503;</span> L&#244;w&#7789;&#226;n, lo-tawn&#39;; from Strong\'s <a href=\"strongs_hebrew.html?strongs=3875&page=1\">H3875</a>; covering; Lotan, an Idumaean:&#8212;Lotan.";
Lex["03878"] = "Leviy {lay-vee'}|AV - Levi 64; 64|from 03867|TWOT - 1093|noun proper masculine|<br><br>Levi = \"joined to\"<BR> INDENT0--<b>1)</b> the 3rd son of Jacob by Leah and progenitor of tribe of Levites <br /><BR /><hr /> INDENT0--<b>Strong\'s Definition</b><BR><BR> INDENT0--<span style=\"font-size:150%\">&#1500;&#1461;&#1493;&#1460;&#1497;</span>  L&#234;v&#238;y, lay-vee'; from Strong\'s <a href=\"strongs_hebrew.html?strongs=3867&page=1\">H3867</a>; attached; Levi, a son of Jacob:&#8212;Levi. See also Strong\'s <a href=\"strongs_hebrew.html?strongs=3879&page=1\">H3879</a>, Strong\'s <a href=\"strongs_hebrew.html?strongs=3881&page=1\">H3881</a>.";
