Lex["05335"] = "n@tsiyach {nets-ee'-akh}|AV - Neziah 2; 2|from 05329||noun proper masculine|<br><br>Neziah = \"pre-eminent\"<BR> INDENT0--<b>1)</b> head of a family of temple slaves returning from exile with Zerubbabel <br /><BR /><hr /> INDENT0--<b>Strong\'s Definition</b><BR><BR> INDENT0--<span style=\"font-size:150%\"> &#1504;&#1456;&#1510;&#1460;&#1497;&#1495;&#1463; </span> n&#7497;ts&#238;yach, nets-ee&#39;-akh; from Strong\'s <a href=\"strongs_hebrew.html?strongs=5329&page=1\">H5329</a>; conspicuous; Netsiach, a Temple-servant:&#8212;Neziah.";
