Lex["05527"] = "C@kakah {sek-aw-kaw'}|AV - Secacah 1; 1|from 05526||noun proper locative|<br><br>Secacah = \"thicket\"<BR> INDENT0--<b>1)</b> one of the 6 cities of Judah located in the wilderness bordering on the Dead Sea <br /><BR /><hr /> INDENT0--<b>Strong\'s Definition</b><BR><BR> INDENT0--<span style=\"font-size:150%\"> &#1505;&#1456;&#1499;&#1464;&#1499;&#1464;&#1492; </span> &#199;&#7497;k&#226;k&#226;h, sek-aw-kaw&#39;; from Strong\'s <a href=\"strongs_hebrew.html?strongs=5526&page=1\">H5526</a>; inclosure; Secacah, a place in Palestine:&#8212;Secacah.";
Lex["05528"] = "cakal {saw-kal'}|AV - done foolishly 5, turn into foolishness 1, make foolish 1,<BR>play the fool 1; 8|for 03688|TWOT - 1493|verb| INDENT0--<b>1)</b> to be foolish, be a fool INDENT3--<b>a)</b> (Piel) to make foolish, turn into foolishness INDENT3--<b>b)</b> (Niphal) to act or do foolishly INDENT3--<b>c)</b> (Hiphil) to do foolishly, play the fool <br /><BR /><hr /> INDENT0--<b>Strong\'s Definition</b><BR><BR> INDENT0--<span style=\"font-size:150%\"> &#1505;&#1464;&#1499;&#1463;&#1500; </span> &#231;&#226;kal, saw-kal&#39;; for Strong\'s <a href=\"strongs_hebrew.html?strongs=3688&page=1\">H3688</a>; to be silly:&#8212;do (make, play the, turn into) fool(-ish, -ishly, -ishness).";
