Lex["08434"] = "Towlad {to-lawd'}|AV - Tolad 1; 1|from 03205||noun proper locative|<br><br>Tolad = \"generation\"<BR> INDENT0--<b>1)</b> a town in Simeon INDENT3--<b>a)</b> also 'El-tolad' <br /><BR /><hr /> INDENT0--<b>Strong\'s Definition</b><BR><BR> INDENT0--<span style=\"font-size:150%\"> &#1514;&#1468;&#1493;&#1465;&#1500;&#1464;&#1491; </span> T&#244;wl&#226;d, to-lawd'; from Strong\'s <a href=\"strongs_hebrew.html?strongs=3205&page=1\">H3205</a>; posterity; Tolad, a place in Palestine:&#8212;Tolad. Compare Strong\'s <a href=\"strongs_hebrew.html?strongs=513&page=1\">H513</a>.";
