Lex["08555"] = "Timna` {tim-naw'}|AV - Timna 4, Timnah 2; 6|from 04513||noun proper masculine, noun proper feminine|<br><br>Timna or Timnah = \"restrained\"<BR><br><br>noun proper masculine<BR><b>1)</b> a chief or duke of Esau and of Edom<br><br>noun proper feminine<BR><b>2)</b> the concubine of Eliphaz, the son of Esau INDENT0--<b>3)</b> daughter of Seir the Horite and sister of Lotan <br /><BR /><hr /> INDENT0--<b>Strong\'s Definition</b><BR><BR> INDENT0--<span style=\"font-size:150%\"> &#1514;&#1468;&#1460;&#1502;&#1456;&#1504;&#1464;&#1506; </span> Timn&#226;&#699;, tim-naw&#39;; from Strong\'s <a href=\"strongs_hebrew.html?strongs=4513&page=1\">H4513</a>; restraint; Timna, the name of two Edomites:&#8212;Timna, Timnah.";
Lex["08556"] = "Timnath Cherec {tim-nath kheh'-res} or Timnath Cerach {tim-nath<br>seh'-rakh}|AV - Timnathserah 2, Timnathheres 1; 3|from 08553 and 02775||noun proper locative|<br><br>Timnath-heres or Timnath-serah = \"portion of the sun\" or<br>\"abundant portion\"<BR> INDENT0--<b>1)</b> a city given to Joshua as a inheritance in the mountains of Ephraim on the north of the hill of Gaash where he was buried <br /><BR /><hr /> INDENT0--<b>Strong\'s Definition</b><BR><BR> INDENT0--<span style=\"font-size:150%\"> &#1514;&#1468;&#1460;&#1502;&#1456;&#1504;&#1463;&#1514; &#1495;&#1462;&#1512;&#1462;&#1505; </span> Timnath Chere&#231;, tim-nath kheh&#39;-res; or <span style=\"font-size:150%\"> &#1514;&#1468;&#1460;&#1502;&#1456;&#1504;&#1463;&#1514; &#1505;&#1462;&#1512;&#1463;&#1495;</span>  Timnath &#xC7;erach; from Strong\'s <a href=\"strongs_hebrew.html?strongs=8553&page=1\">H8553</a> and Strong\'s <a href=\"strongs_hebrew.html?strongs=2775&page=1\">H2775</a>; portion of (the) sun; Timnath-Cheres, a place in Palestine:&#8212;Timnath-heres, Timnath-serah.";
