Lex["08574"] = "tannuwr {tan-noor'}|AV - oven 11, furnace 4; 15|from 05216|TWOT - 2526|noun masculine| INDENT0--<b>1)</b> furnace, oven, fire-pot, (portable) stove INDENT3--<b>a)</b> for cooking INDENT3--<b>b)</b> of God's wrath, His furnace (fig) INDENT3--<b>c)</b> of hunger, desire for evil INDENT3--<b>d)</b> fire-pot <br /><BR /><hr /> INDENT0--<b>Strong\'s Definition</b><BR><BR> INDENT0--<span style=\"font-size:150%\"> &#1514;&#1468;&#1463;&#1504;&#1468;&#1493;&#1468;&#1512; </span> tann&#251;wr, tan-noor&#39;; from Strong\'s <a href=\"strongs_hebrew.html?strongs=5216&page=1\">H5216</a>; a fire-pot:&#8212;furnace, oven.";
